    /// nw-204. Reclaim embedding vectors for nodes that no longer exist.
    ///
    /// Routed through the daemon like every other write: it takes the same
    /// admission guard and write gate, so it cannot race an index, a watcher
    /// batch, or the reconcile loop against a store that is not crash-safe.
    /// An operator running this on a live brain is exactly when a concurrent
    /// write is most likely, which is why it is an RPC rather than a
    /// direct-store command.
    async fn compact_embeddings(
        &self,
        request: Request<CompactEmbeddingsRequest>,
    ) -> Result<Response<CompactEmbeddingsResponse>, Status> {
        if let Some(crate::auth::IsAdmin(false)) | None =
            request.extensions().get::<crate::auth::IsAdmin>()
        {
            return Err(Status::permission_denied("admin token required"));
        }
        let dry_run = request.into_inner().dry_run;
        let state = self.state.clone();

        let compact = move || {
            let sidecar = nestweaver_engine::sidecar_path(&state.db_path, ".embeddings.bin");
            let bytes_of = |path: &std::path::Path| {
                std::fs::metadata(path).map(|meta| meta.len()).unwrap_or(0)
            };

            let before = state.store.embedding_index_occupancy();
            let bytes_before = bytes_of(&sidecar);

            if dry_run {
                return Ok::<_, Status>(CompactEmbeddingsResponse {
                    stored_before: before.stored as u64,
                    tombstoned_before: before.tombstoned as u64,
                    stored_after: before.stored as u64,
                    live_after: before.live as u64,
                    reclaimed: 0,
                    bytes_before,
                    bytes_after: bytes_before,
                    dry_run: true,
                });
            }

            require_verified_embedding_runtime_identity(
                &state.store,
                &state.embedding_runtime.status(),
                "embedding compaction write",
            )?;

            // Reconcile FIRST, always. Compaction rewrites the base without
            // tombstoned rows, so running it alone on a brain whose orphans
            // were never tombstoned reclaims exactly nothing — which is the
            // state every pre-fix brain is in.
            state
                .store
                .reconcile_embedding_index()
                .map_err(|error| Status::internal(format!("compact embeddings failed: {error}")))?;
            if state.store.embedding_index_occupancy().tombstoned > 0 {
                state.store.compact_embedding_index().map_err(|error| {
                    Status::internal(format!("compact embeddings failed: {error}"))
                })?;
            }

            let after = state.store.embedding_index_occupancy();
            Ok(compact_embeddings_response(
                before,
                after,
                bytes_before,
                bytes_of(&sidecar),
            ))
        };

        // A dry run writes nothing and remains outside write admission. The
        // applying path transfers ownership into the exact worker.
        let response = if dry_run {
            tokio::task::spawn_blocking(compact)
                .await
                .map_err(|error| {
                    Status::internal(format!("compact_embeddings task panicked: {error}"))
                })??
        } else {
            self.run_unary_mutation("compact_embeddings", compact)
                .await?
        };

        Ok(Response::new(response))
    }

    async fn merge_instance(
        &self,
        request: Request<MergeInstanceRequest>,
    ) -> Result<Response<MergeInstanceResponse>, Status> {
        if let Some(crate::auth::IsAdmin(false)) | None =
            request.extensions().get::<crate::auth::IsAdmin>()
        {
            return Err(Status::permission_denied("admin token required"));
        }
        let req = request.into_inner();
        let from_id = resolve_effective_instance_id(&req.from_id, &self.state)?;
        let to_id = resolve_effective_instance_id(&req.to_id, &self.state)?;
        if from_id == to_id {
            return Err(Status::invalid_argument(
                "source and target instance IDs must differ",
            ));
        }
        let state = self.state.clone();
        self.run_unary_mutation("merge_instance", move || {
            let result = run_merge_instance_with(
                &state,
                &from_id,
                &to_id,
                |store, from_id, to_id| {
                    store
                        .merge_instance_ids(from_id, to_id)
                        .map_err(|e| anyhow::anyhow!("{e:#}"))
                },
                rebuild_tantivy_after_mutation,
            )?;

            let discarded_vaults = result
                .discarded
                .into_iter()
                .map(|d| format!("{} ({} notes discarded)", d.root_path, d.notes_discarded))
                .collect::<Vec<_>>();

            Ok::<_, Status>(MergeInstanceResponse {
                vaults_reparented: result.vaults as u64,
                repos_reparented: result.repos as u64,
                projects_reparented: result.projects as u64,
                discarded_vaults,
                repos_needing_reindex: result.repos_moved,
                // Reaching here means the merge committed (nw-091 / Bug 2).
                // Reconciliation warnings, if any, are logged by
                // finish_reconciled_mutation; wire-surfacing them for merge would
                // require threading them through the internal MergeResult path.
                committed: true,
                reconciliation_failures: Vec::new(),
            })
        })
        .await
        .map(Response::new)
    }

    type PurgeInstanceStream = ProgressStream;

    async fn purge_instance(
        &self,
        request: Request<PurgeInstanceRequest>,
    ) -> Result<Response<Self::PurgeInstanceStream>, Status> {
        if let Some(crate::auth::IsAdmin(false)) | None =
            request.extensions().get::<crate::auth::IsAdmin>()
        {
            return Err(Status::permission_denied("admin token required"));
        }
        let req = request.into_inner();
        let instance_id = resolve_effective_instance_id(&req.instance_id, &self.state)?;
        let state = self.state.clone();

        let (tx, rx) = tokio::sync::mpsc::channel::<Result<IndexProgress, Status>>(16);

        let guard = ConnectionGuard::write(&self.state)?;
        let write_lock = self.state.write_gate.clone();
        tokio::task::spawn_blocking(move || {
            let _ownership = MutationWorkerOwnership {
                _write_lease: write_lock.blocking_lock("purge_instance"),
                _connection_guard: guard,
            };
            let _ = tx.blocking_send(Ok(IndexProgress {
                phase: Phase::Writing as i32,
                message: format!("Purging instance {instance_id}"),
                files_processed: 0,
                files_total: 0,
                symbols_found: 0,
                ..Default::default()
            }));

            match run_purge_instance_with(
                &state,
                &instance_id,
                |store, id| {
                    store
                        .purge_instance(id)
                        .map_err(|e| anyhow::anyhow!("{e:#}"))
                },
                rebuild_tantivy_after_mutation,
            ) {
                Ok(result) => {
                    let _ = tx.blocking_send(Ok(IndexProgress {
                        phase: Phase::Done as i32,
                        message: format!(
                            "Done — {} repos, {} files, {} symbols, {} vaults, {} notes, {} projects, {} orphans swept",
                            result.repos,
                            result.files,
                            result.symbols,
                            result.vaults,
                            result.notes,
                            result.projects,
                            result.orphans_swept,
                        ),
                        files_processed: (result.repos + result.vaults) as u64,
                        files_total: (result.repos + result.vaults) as u64,
                        symbols_found: result.symbols as u64,
                        ..Default::default()
                    }));
                }
                Err(e) => {
                    let _ = tx.blocking_send(Ok(IndexProgress {
                        phase: Phase::Error as i32,
                        message: e.message().to_string(),
                        files_processed: 0,
                        files_total: 0,
                        symbols_found: 0,
                        ..Default::default()
                    }));
                }
            }
        });

        Ok(Response::new(tokio_stream::wrappers::ReceiverStream::new(
            rx,
        )))
    }

