    async fn reindex_search(
        &self,
        _request: Request<ReindexSearchRequest>,
    ) -> Result<Response<ReindexSearchResponse>, Status> {
        if let Some(crate::auth::IsAdmin(false)) | None =
            _request.extensions().get::<crate::auth::IsAdmin>()
        {
            return Err(Status::permission_denied("admin token required"));
        }
        let state = self.state.clone();
        self.run_unary_mutation("reindex_search", move || {
            let tantivy = state.tantivy().filter(|t| t.has_writer()).ok_or_else(|| {
                Status::failed_precondition("daemon has no writer-mode Tantivy index")
            })?;
            let count = tantivy
                .reindex_from_store(&state.store)
                .map_err(|e| Status::internal(format!("reindex failed: {e:#}")))?;
            clear_search_reconciliation_debt(&state.db_path).map_err(|error| {
                Status::internal(format!(
                    "search index rebuilt, but durable reconciliation debt could not be cleared: {error:#}"
                ))
            })?;
            Ok::<_, Status>(ReindexSearchResponse {
                document_count: count as i32,
            })
        })
        .await
        .map(Response::new)
    }

    // ── Read RPCs — typed hot-path ─────────────────────────────────

    async fn search(
        &self,
        r: Request<BrainSearchRequest>,
    ) -> Result<Response<BrainSearchResponse>, Status> {
        let (_, extensions, req) = r.into_parts();
        let mut args = serde_json::json!({
            "query": req.query,
            "include_bodies": req.include_bodies,
            "prf": req.prf,
            "rerank": req.rerank,
        });
        if req.limit > 0 {
            args["limit"] = serde_json::json!(req.limit);
        }
        if let Some(ref fmt) = req.response_format {
            args["response_format"] = serde_json::json!(fmt);
        }
        if let Some(ref root) = req.root {
            args["root"] = serde_json::json!(root);
        }

        // `brain_search` includes repo-owned symbols, so the typed hot path
        // must enforce the same request-derived scope as generic JSON-RPC.
        let value = self
            .dispatch_tool_json("brain_search", args, &extensions)
            .await?;

        // Parse JSON result into typed response.
        let query_echo = value
            .get("query")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let engine = value
            .get("engine")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let total_matches = value
            .get("total_matches")
            .and_then(|v| v.as_i64())
            .unwrap_or(0) as i32;

        let results: Vec<SearchResultItem> = value
            .get("results")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .map(|item| SearchResultItem {
                        uid: item
                            .get("uid")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string(),
                        canonical_id: item
                            .get("canonical_id")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                            .map(String::from),
                        kind: item
                            .get("kind")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string(),
                        title: item
                            .get("title")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string(),
                        score: item.get("score").and_then(|v| v.as_f64()).unwrap_or(0.0),
                        location: item
                            .get("location")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                            .map(String::from),
                        matched_headings: item
                            .get("matched_headings")
                            .and_then(|v| v.as_array())
                            .map(|a| {
                                a.iter()
                                    .filter_map(|s| s.as_str().map(String::from))
                                    .collect()
                            })
                            .unwrap_or_default(),
                        inline_body: item
                            .get("inline_body")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                            .map(String::from),
                        vault_uid: item
                            .get("vault_uid")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                            .map(String::from),
                    })
                    .collect()
            })
            .unwrap_or_default();

        let expansion_terms = value
            .get("expansion_terms")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|s| s.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        let returned_matches = value
            .get("returned_matches")
            .and_then(|v| v.as_i64())
            .unwrap_or(results.len() as i64) as i32;
        let total_matches_relation = value
            .get("total_matches_relation")
            .and_then(|v| v.as_str())
            .unwrap_or("eq")
            .to_string();
        let explicit_truncated = value
            .get("truncated")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let truncated = explicit_truncated
            || total_matches_relation != "eq"
            || returned_matches < total_matches;
        let semantic_applied = value
            .get("semantic_applied")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let degraded_components = value
            .get("degraded_components")
            .and_then(serde_json::Value::as_array)
            .map(|components| {
                components
                    .iter()
                    .filter_map(|component| component.as_str().map(ToOwned::to_owned))
                    .collect()
            })
            .unwrap_or_default();
        let semantic_unavailable = value
            .get("semantic_unavailable")
            .and_then(serde_json::Value::as_object)
            .map(|detail| SemanticUnavailable {
                cause: detail
                    .get("cause")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
                reason: detail
                    .get("reason")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
                error: detail
                    .get("error")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
                remediation: detail
                    .get("remediation")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
            });

        Ok(Response::new(BrainSearchResponse {
            query: query_echo,
            engine,
            total_matches,
            results,
            expansion_terms,
            returned_matches,
            total_matches_relation,
            truncated,
            // `brain_search` remains keyword/BM25-only. A semantic-identity
            // failure is nevertheless reported as an unavailable optional
            // capability so lexical success cannot be mistaken for full
            // semantic readiness.
            semantic_applied,
            degraded_components,
            semantic_unavailable,
        }))
    }

    /// CODE-only context, distinct from `get_context`'s hybrid.
    ///
    /// `nestweaver context` had no RPC of its own, so its daemon route sent
    /// `brain_context` — code AND notes with alias resolution — while its
    /// direct path ran PPR over the symbol graph alone. One command, two
    /// algorithms over two different node sets, chosen by whether a daemon
    /// happened to be running.
    async fn code_context(
        &self,
        r: Request<JsonRequest>,
    ) -> Result<Response<JsonResponse>, Status> {
        json_rpc!(self, r, "code_context")
    }

    async fn get_context(
        &self,
        r: Request<BrainContextRequest>,
    ) -> Result<Response<BrainContextResponse>, Status> {
        // nw-415: `into_parts`, not `into_inner` — the request's extensions
        // carry the `Identity` the auth interceptor attached, and dispatch
        // resolves the caller's repo scope from them. This handler used to
        // hand `dispatch_tool_json` a literal `VisibleRepos::All`, which made
        // nw-403's whole `repo_scope` table unreachable (see the argument on
        // `dispatch_tool_json`); `code_context`, one method away on the same
        // surface, was scoped the whole time.
        //
        // `brain_context` is one of the tools nw-403's own measurement named
        // as leaking (hidden-repo symbols, file paths and note prose). It is
        // `RepoScope::RedactedAfterDispatch`, so a scoped caller now gets only
        // the rows it owns, and a `response_format: "concise"` request — which
        // omits the very uids attribution needs — is refused rather than
        // served unfiltered.
        let (_, extensions, req) = r.into_parts();
        let mut args = serde_json::json!({
            "seeds": req.seeds,
            "include_seeds": req.include_seeds,
            "include_bodies": req.include_bodies,
            "prf": req.prf,
            "rerank": req.rerank,
        });
        if req.token_budget > 0 {
            args["token_budget"] = serde_json::json!(req.token_budget);
        }
        if !req.response_format.is_empty() {
            args["response_format"] = serde_json::json!(req.response_format);
        }
        if !req.repos.is_empty() {
            args["repos"] = serde_json::json!(req.repos);
        }
        if !req.vaults.is_empty() {
            args["vaults"] = serde_json::json!(req.vaults);
        }
        if !req.kinds.is_empty() {
            args["kinds"] = serde_json::json!(req.kinds);
        }
        if !req.path_prefix.is_empty() {
            args["path_prefix"] = serde_json::json!(req.path_prefix);
        }
        if !req.tags.is_empty() {
            args["tags"] = serde_json::json!(req.tags);
        }
        if !req.exclude_tags.is_empty() {
            args["exclude_tags"] = serde_json::json!(req.exclude_tags);
        }
        if req.weight_ppr != 0.0 {
            args["weight_ppr"] = serde_json::json!(req.weight_ppr);
        }
        if req.weight_bm25 != 0.0 {
            args["weight_bm25"] = serde_json::json!(req.weight_bm25);
        }
        if !req.intent.is_empty() {
            args["intent"] = serde_json::json!(req.intent);
        }
        if !req.root.is_empty() {
            args["root"] = serde_json::json!(req.root);
        }
        if !req.since.is_empty() {
            args["since"] = serde_json::json!(req.since);
        }
        if req.weight_semantic > 0.0 {
            args["weight_semantic"] = serde_json::json!(req.weight_semantic);
        }
        if req.recency_weight > 0.0 {
            args["recency_weight"] = serde_json::json!(req.recency_weight);
        }
        if req.recency_half_life_days > 0.0 {
            args["recency_half_life_days"] = serde_json::json!(req.recency_half_life_days);
        }

        let value = self
            .dispatch_tool_json("brain_context", args, &extensions)
            .await?;
        let result_json = serde_json::to_string(&value)
            .map_err(|e| Status::internal(format!("failed to serialize result: {e}")))?;
        let semantic_applied = value
            .get("semantic_applied")
            .and_then(|value| value.as_bool())
            .unwrap_or(false);
        let degraded_components = value
            .get("degraded_components")
            .and_then(|value| value.as_array())
            .map(|values| {
                values
                    .iter()
                    .filter_map(|value| value.as_str().map(ToOwned::to_owned))
                    .collect()
            })
            .unwrap_or_default();

        Ok(Response::new(BrainContextResponse {
            result_json,
            semantic_applied,
            degraded_components,
        }))
    }

    async fn get_project_context(
        &self,
        r: Request<ProjectContextRequest>,
    ) -> Result<Response<ProjectContextResponse>, Status> {
        // nw-415, argued at `dispatch_tool_json`. `project_context` is
        // `RepoScope::RedactedAfterDispatch` AND its `response_format`
        // DEFAULTS to concise, so a repo-scoped caller that sends no format at
        // all is refused rather than handed uid-free rows that nothing
        // downstream can attribute to a repo.
        let (_, extensions, req) = r.into_parts();
        let mut args = serde_json::json!({
            "project": req.project,
            "include_seeds": req.include_seeds,
        });
        // nw-316: only when the caller actually said so. Injecting it
        // unconditionally re-erased the absence the `optional` field exists to
        // carry, so the tool's documented default of `true` stayed unreachable.
        if let Some(include_components) = req.include_components {
            args["include_components"] = serde_json::json!(include_components);
        }
        if req.token_budget > 0 {
            args["token_budget"] = serde_json::json!(req.token_budget);
        }
        if !req.kinds.is_empty() {
            args["kinds"] = serde_json::json!(req.kinds);
        }
        if !req.intent.is_empty() {
            args["intent"] = serde_json::json!(req.intent);
        }
        if !req.since.is_empty() {
            args["since"] = serde_json::json!(req.since);
        }
        if req.recency_weight > 0.0 {
            args["recency_weight"] = serde_json::json!(req.recency_weight);
        }
        if req.recency_half_life_days > 0.0 {
            args["recency_half_life_days"] = serde_json::json!(req.recency_half_life_days);
        }
        if !req.response_format.is_empty() {
            args["response_format"] = serde_json::json!(req.response_format);
        }
        if !req.repos.is_empty() {
            args["repos"] = serde_json::json!(req.repos);
        }
        if !req.path_prefix.is_empty() {
            args["path_prefix"] = serde_json::json!(req.path_prefix);
        }
        if !req.tags.is_empty() {
            args["tags"] = serde_json::json!(req.tags);
        }
        if !req.exclude_tags.is_empty() {
            args["exclude_tags"] = serde_json::json!(req.exclude_tags);
        }

        let value = self
            .dispatch_tool_json("project_context", args, &extensions)
            .await?;
        let result_json = serde_json::to_string(&value)
            .map_err(|e| Status::internal(format!("failed to serialize result: {e}")))?;

        Ok(Response::new(ProjectContextResponse { result_json }))
    }

    async fn get_note(
        &self,
        r: Request<NoteGetRequest>,
    ) -> Result<Response<NoteGetResponse>, Status> {
        // nw-415, argued at `dispatch_tool_json`. `note_get` is the one of
        // the six that carries a WRITTEN `RepoScope::NotRepoScoped` exemption
        // (Note/Section/Heading nodes belong to a vault and have no
        // `repo_uid`), so routing the identity here is not expected to change
        // its answer. It is routed anyway because the exemption has to be the
        // TABLE's decision — logged, falsifiable, and revisitable if `note_get`
        // ever grows a repo-derived field — not a `VisibleRepos::All` literal
        // at a call site no policy can reach.
        let (_, extensions, req) = r.into_parts();
        let mut args = serde_json::json!({});
        // nw-316: omit when the caller did not say, so the tool's documented
        // default governs instead of proto3's zero value.
        if let Some(include_body) = req.include_body {
            args["include_body"] = serde_json::json!(include_body);
        }
        if let Some(ref uid) = req.uid {
            args["uid"] = serde_json::json!(uid);
        }
        if let Some(ref title) = req.title {
            args["title"] = serde_json::json!(title);
        }
        if !req.sections.is_empty() {
            args["sections"] = serde_json::json!(req.sections);
        }

        let value = self
            .dispatch_tool_json("note_get", args, &extensions)
            .await?;

        Ok(Response::new(NoteGetResponse {
            uid: value
                .get("uid")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string(),
            title: value
                .get("title")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string(),
            path: value
                .get("path")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string(),
            note_kind: value
                .get("note_kind")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string(),
            word_count: value
                .get("word_count")
                .and_then(|v| v.as_i64())
                .unwrap_or(0) as i32,
            body: value
                .get("body")
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(String::from),
            section_count: value
                .get("section_count")
                .and_then(|v| v.as_i64())
                .unwrap_or(0) as i32,
            // Parity with the local note_get JSON: frontmatter (a JSON object)
            // and the heading outline ride the typed response too — the MCP
            // daemon path used to drop both.
            frontmatter_json: value
                .get("frontmatter")
                .map(|v| v.to_string())
                .unwrap_or_default(),
            outline: value
                .get("outline")
                .and_then(|v| v.as_array())
                .map(|arr| {
                    arr.iter()
                        .map(|h| nestweaver_proto::NoteHeading {
                            uid: h
                                .get("uid")
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string(),
                            level: h.get("level").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
                            text: h
                                .get("text")
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string(),
                            slug: h
                                .get("slug")
                                .and_then(|v| v.as_str())
                                .unwrap_or("")
                                .to_string(),
                            line: h.get("line").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
                        })
                        .collect()
                })
                .unwrap_or_default(),
        }))
    }

    async fn brain_status(
        &self,
        r: Request<BrainStatusRequest>,
    ) -> Result<Response<BrainStatusResponse>, Status> {
        // nw-415, argued at `dispatch_tool_json`. `brain_status` is the most
        // direct enumeration in the catalogue — nw-403 gave it its own
        // `RepoScope::EnforcedInArm` treatment because `repos[]` carries each
        // repo's URL and indexed git SHA, i.e. repo IDENTITY rather than repo
        // content. Handing it `All` meant the enforcing arm was never reached
        // and `repo_count` counted tenants the caller cannot see.
        // `indexing_repo` is the worker job's configured repo identifier, not
        // an authoritative graph repo UID. It therefore cannot be filtered
        // through the repo-scope policy used for `repos[]`; suppress it for
        // every restricted identity instead of risking a cross-tenant name
        // leak from this process-level status field.
        let restricted = matches!(
            self.state.visible_repos_for(r.extensions())?,
            nestweaver_engine::authz::VisibleRepos::Only(_)
        );
        let (_, extensions, _) = r.into_parts();
        let args = serde_json::json!({});
        let value = self
            .dispatch_tool_json("brain_status", args, &extensions)
            .await?;

        let indexing_active = self.state.indexing_active.load(Ordering::Relaxed);
        let indexing_repo = if indexing_active && !restricted {
            self.state.indexing_repo.read().await.clone()
        } else {
            String::new()
        };
        let queue_depth = self.state.indexing_queue_depth.load(Ordering::Relaxed) as i32;
        let embedding_runtime_status = embedding_status_with_store_identity(
            self.state.embedding_runtime.status(),
            &self.state.store,
        );
        let embedding_status = embedding_status_proto(
            &embedding_runtime_status,
            &self.state.embed_progress.snapshot(),
            self.state.store.embedding_index_occupancy(),
            &self.state.store,
        );
        let search_status = search_capability_status(&self.state);
        let write_queue_depth = self.state.write_gate.waiting() as i32;
        let (write_holder, write_holder_seconds) = self
            .state
            .write_gate
            .holder_snapshot()
            .map(|(rpc, held)| (rpc, held.as_secs() as i64))
            .unwrap_or_else(|| (String::new(), 0));

        Ok(Response::new(BrainStatusResponse {
            vault_count: value
                .get("vault_count")
                .and_then(|v| v.as_i64())
                .unwrap_or(0) as i32,
            notes: value.get("notes").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
            headings: value.get("headings").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
            sections: value.get("sections").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
            tags: value.get("tags").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
            wikilinks: value.get("wikilinks").and_then(|v| v.as_i64()).unwrap_or(0) as i32,
            repo_count: value
                .get("repo_count")
                .and_then(|v| v.as_i64())
                .unwrap_or(0) as i32,
            tantivy_available: value
                .get("tantivy_available")
                .and_then(|v| v.as_bool())
                .unwrap_or(false),
            tantivy_doc_count: value
                .get("tantivy_doc_count")
                .and_then(|v| v.as_i64())
                .unwrap_or(0) as i32,
            indexing_active,
            indexing_repo,
            queue_depth,
            embedding_status: Some(embedding_status),
            effective_config: Some(effective_config_proto(&self.state.effective_config)),
            write_queue_depth,
            write_holder,
            write_holder_seconds,
            search_status: Some(search_status_proto(&search_status)),
        }))
    }

