    /// Class B (the same lifetime error as nw-286, in the field beside it):
    /// a daemon that could not open its search index at BOOT must be able to
    /// pick it up later.
    ///
    /// `tantivy` and `search_reconciliation` were opened once from the
    /// filesystem during `serve()` and had no re-open path, so a daemon that
    /// started while the sidecar was locked — or before it existed — answered
    /// every search from the substring fallback for its ENTIRE life, and said
    /// so in exactly one boot-time log line. Repairing the sidecar externally
    /// changed nothing until the process was restarted.
    ///
    /// The failure is induced with a plain FILE where the index directory
    /// belongs: `open_or_create` cannot `create_dir_all` over it and
    /// `open_reader_only` cannot read it, which is exactly the (None,
    /// Unavailable) boot state the defect describes.
    #[test]
    fn a_search_index_that_could_not_be_opened_at_boot_is_reopened_later() {
        let dir = tempfile::tempdir().unwrap();
        let tantivy_path = dir.path().join("tantivy");
        // A file, not a directory: the index cannot be opened over it.
        std::fs::write(&tantivy_path, b"not an index").unwrap();

        let runtime = SearchRuntime::with_retry_interval(
            tantivy_path.clone(),
            false,
            std::time::Duration::ZERO,
        );
        let booted = runtime.snapshot();
        assert!(
            booted.tantivy.is_none(),
            "precondition: the daemon boots with no search index — this is the \
             state the defect is about"
        );
        assert!(!booted.is_healthy());

        // The obstruction clears — an operator repaired the sidecar, or the
        // process that held it exited. Nothing restarts the daemon.
        std::fs::remove_file(&tantivy_path).unwrap();

        let recovered = runtime.snapshot();
        assert!(
            recovered.tantivy.is_some(),
            "a repaired sidecar must be picked up without a daemon restart; \
             holding None here is the Class B freeze — substring-fallback \
             search for the whole life of the process"
        );
        assert!(matches!(
            recovered.reconciliation,
            SearchIndexReconciliation::Available(_)
        ));
        assert!(
            recovered.tantivy.as_ref().unwrap().has_writer(),
            "and it must be the WRITER, or index and vault mutations still \
             never reach BM25"
        );
    }

    /// The retry must be throttled and must never DOWNGRADE what it already
    /// has. A burst of queries against a still-broken sidecar would otherwise
    /// pay a failed open each, and a harder failure on a later attempt must
    /// not turn a working reader-only fallback into nothing.
    #[test]
    fn a_still_broken_search_index_is_retried_at_most_once_per_interval() {
        let dir = tempfile::tempdir().unwrap();
        let tantivy_path = dir.path().join("tantivy");
        std::fs::write(&tantivy_path, b"not an index").unwrap();

        let runtime = SearchRuntime::with_retry_interval(
            tantivy_path.clone(),
            false,
            std::time::Duration::from_secs(3600),
        );
        assert!(runtime.snapshot().tantivy.is_none());

        // Repair it, but stay inside the retry window: still no index.
        std::fs::remove_file(&tantivy_path).unwrap();
        assert!(
            runtime.snapshot().tantivy.is_none(),
            "the retry window must actually bound the reopen attempts, or a \
             broken sidecar costs a failed open on every query"
        );
    }

    /// A healthy runtime must never re-open. This is the fence that keeps the
    /// recovery free for the overwhelmingly common case.
    #[test]
    fn a_healthy_search_index_is_never_reopened() {
        let dir = tempfile::tempdir().unwrap();
        let tantivy_path = dir.path().join("tantivy");
        let runtime =
            SearchRuntime::with_retry_interval(tantivy_path, false, std::time::Duration::ZERO);
        let first = runtime.snapshot();
        assert!(matches!(
            first.reconciliation,
            SearchIndexReconciliation::Available(_)
        ));
        let first_handle = first.tantivy.unwrap();
        let second_handle = runtime.snapshot().tantivy.unwrap();
        assert!(
            Arc::ptr_eq(&first_handle, &second_handle),
            "a healthy runtime must hand back the SAME handle, not re-open"
        );
    }

    #[test]
    fn search_debt_clears_only_after_a_proven_noop_or_successful_rebuild() {
        let state = test_state_with_writer();
        let admission = establish_search_reconciliation_debt(&state, "index_vault").unwrap();
        state
            .search
            .set_reconciliation(SearchIndexReconciliation::Unavailable(
                "writer lock held".to_string(),
            ));

        finish_search_reconciliation(
            &state,
            IndexedSearchMutation::Unchanged,
            "index_vault",
            admission,
        )
        .expect("a newly established proven no-op needs no writer and may clear debt");
        assert!(
            load_search_reconciliation_debt(&state.db_path)
                .unwrap()
                .is_none()
        );

        let admission =
            establish_search_reconciliation_debt(&state, "refresh_vault_since").unwrap();
        let error = finish_search_reconciliation(
            &state,
            IndexedSearchMutation::Changed,
            "refresh_vault_since",
            admission,
        )
        .expect_err("a changed corpus without a writer must remain degraded");
        assert!(format!("{error:#}").contains("writer lock held"));
        let debt = load_search_reconciliation_debt(&state.db_path)
            .unwrap()
            .expect("failed reconciliation remains durable");
        assert_eq!(debt.operation, "refresh_vault_since");
        assert_eq!(debt.attempts, 1);

        let status = search_capability_status(&state);
        assert!(status.reader_available);
        assert!(!status.writer_available);
        assert!(!status.current);
        assert!(status.reconciliation_debt);
        assert!(status.error.contains("writer lock held"));
    }

    #[test]
    fn a_later_noop_cannot_clear_an_earlier_failed_search_reconciliation() {
        let state = test_state_with_writer();
        let first = establish_search_reconciliation_debt(&state, "index_vault").unwrap();
        state
            .search
            .set_reconciliation(SearchIndexReconciliation::Unavailable(
                "writer lock held".to_string(),
            ));
        finish_search_reconciliation(&state, IndexedSearchMutation::Changed, "index_vault", first)
            .expect_err("the first failed rebuild must leave durable debt");

        let second = establish_search_reconciliation_debt(&state, "refresh_vault_since").unwrap();
        assert!(second.had_existing_debt);
        finish_search_reconciliation(
            &state,
            IndexedSearchMutation::Unchanged,
            "refresh_vault_since",
            second,
        )
        .expect_err("a later no-op must retry, not erase, the earlier debt");
        assert!(
            load_search_reconciliation_debt(&state.db_path)
                .unwrap()
                .is_some()
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn startup_retries_durable_search_debt_under_writer_ownership() {
        let state = test_state_with_writer();
        establish_search_reconciliation_debt(&state, "index_vault").unwrap();
        assert!(
            load_search_reconciliation_debt(&state.db_path)
                .unwrap()
                .is_some()
        );

        retry_search_reconciliation_debt_at_startup(&state)
            .await
            .expect("healthy startup writer rebuilds the corpus");

        assert!(
            load_search_reconciliation_debt(&state.db_path)
                .unwrap()
                .is_none(),
            "successful startup rebuild is the clearing proof"
        );
        assert!(search_capability_status(&state).current);
        assert_eq!(state.active_writes.load(Ordering::Relaxed), 0);
        assert!(state.write_gate.holder_snapshot().is_none());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_live_writer_schedules_durable_debt_recovery_under_the_write_gate() {
        let state = test_state_with_writer();
        state.search.attach_recovery_context(&state);
        establish_search_reconciliation_debt(&state, "index_vault").unwrap();

        let held = state.write_gate.mutex().lock_owned().await;
        assert!(
            state.tantivy().is_some(),
            "reader remains usable while debt waits"
        );
        tokio::time::timeout(Duration::from_secs(5), async {
            while state.active_writes.load(Ordering::Relaxed) == 0 {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("debt recovery must enter write admission before waiting");
        assert!(
            load_search_reconciliation_debt(&state.db_path)
                .unwrap()
                .is_some(),
            "the marker cannot clear before the recovery owns the writer gate"
        );

        drop(held);
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                if load_search_reconciliation_debt(&state.db_path)
                    .unwrap()
                    .is_none()
                    && state.active_writes.load(Ordering::Relaxed) == 0
                {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("recovered writer must rebuild and clear durable debt");
    }

